                        2: begin
                            head <= middle;
                            middle <= in_data;
                        end
                        3: begin
                            head <= middle;
                            middle <= tail;
                            tail <= in_data;
                        end
                        default: begin end
                    endcase
                end

                default: begin
                    occupancy <= occupancy;
                end
